import pickle

import pytest

from mesa.agent import Agent, AgentSet
from mesa.model import Model


class TestAgent(Agent):
    def get_unique_identifier(self):
        return self.unique_id


class TestAgentDo(Agent):
    def __init__(
        self,
        unique_id,
        model,
    ):
        super().__init__(unique_id, model)
        self.agent_set = None

    def get_unique_identifier(self):
        return self.unique_id

    def do_add(self):
        agent = TestAgentDo(self.model.next_id(), self.model)
        self.agent_set.add(agent)

    def do_remove(self):
        self.agent_set.remove(self)


def test_agent_removal():
    model = Model()
    agent = TestAgent(model.next_id(), model)
    # Check if the agent is added
    assert agent in model.agents

    agent.remove()
    # Check if the agent is removed
    assert agent not in model.agents

